-- 0183: Oshi no Ko — die Sprecherangabe zu Nino (Kana Hanazawa) war nicht belegbar; neue Erklärung. Idempotent.
update question_translations set explanation = 'Her full name is Fuyuko Niino – “Nino” is her nickname.' where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Welches Gründungsmitglied der alten B-Komachi war tief eifersüchtig auf Ai?');
